package com.travbook.stays.adapter.out.commerce;
import com.travbook.stays.application.port.out.StayEffects;
import com.travbook.stays.domain.model.Stay.*;
import com.travbook.hotels.application.port.in.HotelReservations;
import com.travbook.payments.application.port.in.*;
import java.util.*;
public final class StayEffectAdapter implements StayEffects {
 private final PaymentOperations payments;private final PaymentRefunds refunds;private final HotelReservations supplier;
 public StayEffectAdapter(PaymentOperations payments,PaymentRefunds refunds,HotelReservations supplier){this.payments=payments;this.refunds=refunds;this.supplier=supplier;}
 public Optional<Result> lookup(Booking b,Step step){if(step.name().startsWith("CHANGE_"))return changeLookup(b,step);UUID op=b.operation(step==Step.REFUND_STATUS?Step.REFUND:step);return switch(step){case AUTHORIZE,CAPTURE,VOID->payments.lookup(op).map(r->{check(b,r.paymentId(),r.amount(),r.currency(),r.mode());String expected=switch(step){case AUTHORIZE->"AUTHORIZED";case CAPTURE->"CAPTURED";case VOID->"VOIDED";default->throw new IllegalStateException();};if(!r.operationId().equals(op)||r.accepted()!=r.state().name().equals(expected)||!r.accepted()&&!(step==Step.AUTHORIZE&&r.state()==com.travbook.payments.domain.model.Payment.State.DECLINED||step==Step.CAPTURE&&r.state()==com.travbook.payments.domain.model.Payment.State.AUTHORIZED)||r.reference()==null||!r.reference().startsWith("MOCK-PAY-"))throw new IllegalStateException("Payment receipt state or operation mismatch");return new Result(r.accepted(),true,r.reference());});case RESERVE,CANCEL,AMEND->supplier.lookup(op).map(r->{String expected=step==Step.CANCEL?"CANCELLED":"CONFIRMED";if(!r.operationId().equals(op)||!r.reservationId().equals(b.id())||!r.mode().equals("MOCK")||r.accepted()!=r.status().equals(expected)||!r.accepted()&&!r.status().equals("REJECTED")||r.reference()==null||!r.reference().startsWith("MOCK-STAY-"))throw new IllegalStateException("Supplier binding or state mismatch");return new Result(r.accepted(),true,r.reference());});case REFUND,REFUND_STATUS->refunds.lookup(op).map(r->{if(!r.operationId().equals(op)||!r.paymentId().equals(b.currentPaymentId())||!r.mode().equals("MOCK")||!r.currency().equals("INR")||r.amount().compareTo(b.cancellation().quote().refundAmount().amount())!=0||r.reference()==null||!r.reference().startsWith("MOCK-REFUND-"))throw new IllegalStateException("Refund binding mismatch");return new Result(true,r.completed(),r.reference());});default->Optional.empty();};}
 private void check(Booking b,UUID id,java.math.BigDecimal amount,String currency,String mode){if(!id.equals(b.id())||amount.compareTo(b.quote().selection().total().amount())!=0||!currency.equals("INR")||!mode.equals("MOCK"))throw new IllegalStateException("Payment binding mismatch");}
 public Result execute(Booking b,Step step){if(step.name().startsWith("CHANGE_"))return changeExecute(b,step);UUID op=b.operation(step==Step.REFUND_STATUS?Step.REFUND:step);switch(step){
  case AUTHORIZE,CAPTURE,VOID->{payments.execute(new PaymentOperations.Command(op,b.id(),b.quote().owner(),com.travbook.payments.domain.model.Payment.Operation.valueOf(step.name()),b.quote().selection().total().amount(),"INR",b.quote().effectiveExpiry(),step==Step.AUTHORIZE&&b.scenario()==Scenario.AUTH_DECLINED||step==Step.CAPTURE&&b.scenario()==Scenario.CAPTURE_DECLINED));if(step==Step.CAPTURE&&b.scenario()==Scenario.CAPTURE_RESPONSE_LOST)throw new IllegalStateException("Simulated capture response loss");}
  case AMEND->{var a=b.amendments().getLast();var q=a.quote();var current=b.currentQuote().selection();supplier.amend(new HotelReservations.AmendmentCommand(op,b.id(),current.criteria(),current.offers().stream().map(o->o.id()).toList(),new HotelReservations.Command(op,b.id(),q.selection().criteria(),q.selection().offers(),q.effectiveExpiry(),false)));if(a.responseLoss())throw new IllegalStateException("Simulated amendment response loss");}
  case RESERVE->{supplier.reserve(new HotelReservations.Command(op,b.id(),b.quote().selection().criteria(),b.quote().selection().offers(),b.quote().effectiveExpiry(),b.scenario()==Scenario.RESERVATION_REJECTED));if(b.scenario()==Scenario.RESERVATION_RESPONSE_LOST)throw new IllegalStateException("Simulated reservation response loss");}
  case CANCEL->{supplier.cancel(op,b.id());if(b.cancellation()!=null&&b.cancellation().simulateResponseLoss())throw new IllegalStateException("Simulated cancellation response loss");}
  case REFUND->{var c=b.cancellation();refunds.submit(new PaymentRefunds.Command(op,b.currentPaymentId(),b.quote().owner(),c.quote().id(),c.quote().refundAmount().amount(),"INR",c.simulateDelay(),b.correlationId(),c.commandId()));if(c.simulateResponseLoss())throw new IllegalStateException("Simulated refund response loss");}
  case REFUND_STATUS->throw new IllegalStateException("Pending refund has no provider receipt");
  default->throw new IllegalStateException("Unsupported effect");
 }return lookup(b,step).orElseThrow();}

 private Optional<Result> changeLookup(Booking b,Step step){var c=b.change();UUID op=c.operation(step);return switch(step){
  case CHANGE_AUTHORIZE,CHANGE_CAPTURE,CHANGE_VOID->payments.lookup(op).map(r->{String expected=step==Step.CHANGE_AUTHORIZE?"AUTHORIZED":step==Step.CHANGE_CAPTURE?"CAPTURED":"VOIDED";if(!r.operationId().equals(op)||!r.paymentId().equals(c.id())||!r.mode().equals("MOCK")||!r.currency().equals("INR")||r.amount().compareTo(c.quote().selection().total().amount())!=0||r.accepted()!=r.state().name().equals(expected)||!r.accepted()&&!(step==Step.CHANGE_AUTHORIZE&&r.state().name().equals("DECLINED")||step==Step.CHANGE_CAPTURE&&r.state().name().equals("AUTHORIZED"))||!r.reference().equals("MOCK-PAY-"+c.id()))throw new IllegalStateException("Replacement payment receipt mismatch");return new Result(r.accepted(),true,r.reference());});
  case CHANGE_RESERVE->supplier.lookup(op).map(r->{if(!r.operationId().equals(op)||!r.reservationId().equals(b.id())||!r.mode().equals("MOCK")||r.accepted()!=r.status().equals("CONFIRMED")||!r.accepted()&&!r.status().equals("REJECTED")||!r.reference().equals("MOCK-STAY-"+b.id()))throw new IllegalStateException("Replacement reservation receipt mismatch");return new Result(r.accepted(),true,r.reference());});
  case CHANGE_REFUND,CHANGE_REFUND_STATUS->refunds.lookup(op).map(r->{if(!r.operationId().equals(op)||!r.paymentId().equals(c.refundPaymentId())||!r.mode().equals("MOCK")||!r.currency().equals("INR")||r.amount().compareTo(c.refundAmount().amount())!=0||r.reference()==null||!r.reference().startsWith("MOCK-REFUND-"))throw new IllegalStateException("Replacement refund receipt mismatch");return new Result(true,r.completed(),r.reference());});
  default->Optional.empty();};}
 private Result changeExecute(Booking b,Step step){var c=b.change();UUID op=c.operation(step);switch(step){
  case CHANGE_AUTHORIZE,CHANGE_CAPTURE,CHANGE_VOID->{if(step==Step.CHANGE_AUTHORIZE){var source=payments.current(c.sourcePaymentId()).orElseThrow(()->new IllegalStateException("Original funding unknown"));if(!source.paymentId().equals(c.sourcePaymentId())||!source.owner().equals(b.quote().owner())||!source.state().name().equals("CAPTURED")||!source.mode().equals("MOCK")||!source.currency().equals("INR")||source.amount().compareTo(c.sourceAmount().amount())!=0||source.committedRefunds().signum()!=0||source.settledRefunds().signum()!=0)throw new IllegalStateException("Original funding inconsistent");}var operation=com.travbook.payments.domain.model.Payment.Operation.valueOf(step.name().substring(7));payments.execute(new PaymentOperations.Command(op,c.id(),b.quote().owner(),operation,c.quote().selection().total().amount(),"INR",c.quote().effectiveExpiry(),step==Step.CHANGE_AUTHORIZE&&c.scenario()==Scenario.AUTH_DECLINED||step==Step.CHANGE_CAPTURE&&c.scenario()==Scenario.CAPTURE_DECLINED));}
  case CHANGE_RESERVE->{var old=c.previousQuote().selection();var q=c.quote();supplier.change(new HotelReservations.ChangeCommand(op,b.id(),old.criteria(),old.offers().stream().map(o->o.id()).toList(),new HotelReservations.Command(op,b.id(),q.selection().criteria(),q.selection().offers(),q.effectiveExpiry(),c.scenario()==Scenario.RESERVATION_REJECTED),c.guests().stream().map(g->new HotelReservations.Guest(g.roomIndex(),g.givenName(),g.familyName(),g.dateOfBirth())).toList()));}
  case CHANGE_REFUND->{refunds.submit(new PaymentRefunds.Command(op,c.refundPaymentId(),b.quote().owner(),c.id(),c.refundAmount().amount(),"INR",c.refundDelay(),b.correlationId(),c.id()));}
  default->throw new IllegalStateException("Replacement receipt missing");}
  if(c.responseLoss()||step==Step.CHANGE_RESERVE&&c.scenario()==Scenario.RESERVATION_RESPONSE_LOST||step==Step.CHANGE_CAPTURE&&c.scenario()==Scenario.CAPTURE_RESPONSE_LOST)throw new IllegalStateException("Simulated replacement response loss");return changeLookup(b,step).orElseThrow();}
 public Optional<com.travbook.shared.domain.Recovery.Proof> verifiedLegacyOutcome(Booking b){
  if(b.modern()||b.status()!=Status.REVIEW)return Optional.empty();
  var pay=payments.current(b.id()).orElse(null);var allocation=supplier.current(b.id()).orElse(null);
  if(pay==null||allocation==null||!pay.paymentId().equals(b.id())||!pay.owner().equals(b.quote().owner())||pay.state()!=com.travbook.payments.domain.model.Payment.State.CAPTURED||!pay.mode().equals("MOCK")||!pay.currency().equals("INR")||pay.amount().compareTo(b.quote().selection().total().amount())!=0||!allocation.reservationId().equals(b.id())||!allocation.mode().equals("MOCK")||!allocation.reference().equals("MOCK-STAY-"+b.id()))return Optional.empty();
  var capture=lookup(b,Step.CAPTURE).orElse(null);var reserve=lookup(b,Step.RESERVE).orElse(null);
  if(capture==null||reserve==null||!capture.accepted()||!reserve.accepted()||!capture.reference().equals(pay.reference())||!reserve.reference().equals(allocation.reference()))return Optional.empty();
  boolean fulfilled=b.cancellation()==null;String refundState="NONE",refundRef=null;int expectedUnits=Math.toIntExact(java.time.temporal.ChronoUnit.DAYS.between(b.quote().selection().criteria().checkIn(),b.quote().selection().criteria().checkOut()))*b.quote().selection().offers().size();
  if(fulfilled){if(!allocation.status().equals("CONFIRMED")||allocation.activeUnits()!=expectedUnits||pay.committedRefunds().signum()!=0||pay.settledRefunds().signum()!=0)return Optional.empty();}
  else{var cancelled=lookup(b,Step.CANCEL).orElse(null);var amount=b.cancellation().quote().refundAmount().amount();if(cancelled==null||!cancelled.accepted()||!allocation.status().equals("CANCELLED")||allocation.activeUnits()!=0||pay.committedRefunds().compareTo(amount)!=0||pay.settledRefunds().compareTo(amount)!=0)return Optional.empty();if(amount.signum()>0){var refund=lookup(b,Step.REFUND).orElse(null);if(refund==null||!refund.completed())return Optional.empty();refundState="SUCCEEDED";refundRef=refund.reference();}else refundState="NOT_DUE";}
  return Optional.of(new com.travbook.shared.domain.Recovery.Proof(b.id(),fulfilled?com.travbook.shared.domain.Recovery.Outcome.FULFILLED:com.travbook.shared.domain.Recovery.Outcome.CANCELLED,"MOCK",pay.reference(),allocation.reference(),refundRef,allocation.status(),refundState,pay.amount(),pay.committedRefunds(),pay.settledRefunds(),pay.currency(),allocation.activeUnits(),b.operation(Step.CAPTURE),b.operation(Step.RESERVE),fulfilled?null:b.operation(Step.CANCEL),!fulfilled&&refundState.equals("SUCCEEDED")?b.operation(Step.REFUND):null));
 }
}
